<template>
  <section aria-label="检验项目映射与来源治理" class="laboratory-management">
    <p v-if="!allowed">仅超级管理员可管理检验项目映射及全院来源审计。</p>
    <template v-else>
      <p>映射审核仅核对来源系统、项目身份、单位、方法和标本；不验证临床模型，不转换原值，不自动启用AI。草稿、发布和撤销保留版本，变更须另建映射。</p>
      <el-tabs v-model="tab">
        <el-tab-pane label="项目映射" name="mappings">
          <el-button type="primary" @click="openCreate">新建项目映射草稿</el-button>
          <el-select v-model="mappingStatus" aria-label="项目映射状态筛选" clearable placeholder="全部状态"><el-option label="草稿" value="draft" /><el-option label="已发布" value="published" /><el-option label="已撤销" value="revoked" /></el-select>
          <el-button :loading="loading" @click="load">查询项目映射</el-button>
          <el-table :data="items" v-loading="loading" empty-text="本页没有项目映射">
            <el-table-column prop="source_namespace" label="来源命名空间" min-width="170" /><el-table-column label="原精确签名" min-width="260"><template #default="{ row }">{{ signatureLabel(row.signature) }}</template></el-table-column><el-table-column label="项目身份" min-width="160"><template #default="{ row }">{{ row.label || row.analyte_label || row.analyte_key }}</template></el-table-column><el-table-column label="状态与版本" min-width="130"><template #default="{ row }">{{ statusLabel(row.status) }} · v{{ row.revision }}</template></el-table-column><el-table-column label="核对" width="130"><template #default="{ row }"><el-button @click="inspectMapping(row)">核对项目映射</el-button></template></el-table-column>
          </el-table>
        </el-tab-pane>
        <el-tab-pane label="检验来源全院审计" name="sources">
          <el-form inline @submit.prevent="load"><el-form-item label="患者ID"><el-input v-model="filters.patient_id" aria-label="检验来源治理患者ID" inputmode="numeric" clearable /></el-form-item><el-form-item label="原住院ID"><el-input v-model="filters.admission_id" aria-label="检验来源治理原住院ID" clearable /></el-form-item><el-form-item label="状态"><el-select v-model="filters.status" aria-label="检验来源治理状态" clearable placeholder="全部状态"><el-option label="活动" value="active" /><el-option label="已撤销" value="revoked" /></el-select></el-form-item><el-button native-type="submit" :loading="loading">查询全院检验来源</el-button></el-form>
          <p>清单保留任务当时的检验记录；点击详情查看原值和当前来源状态。</p>
          <el-table :data="items" v-loading="loading" empty-text="本页没有匹配检验来源"><el-table-column prop="lab_source_id" label="来源ID" min-width="250" /><el-table-column label="原患者与住院" min-width="220"><template #default="{ row }">#{{ row.patient_id }} · {{ row.admission_id }}</template></el-table-column><el-table-column prop="collected_at_utc" label="人工核实采样UTC" min-width="220" /><el-table-column prop="available_at" label="本次纳入可用UTC" min-width="220" /><el-table-column label="状态与版本"><template #default="{ row }">{{ statusLabel(row.status) }} · v{{ row.revision }}</template></el-table-column><el-table-column label="核对" width="130"><template #default="{ row }"><el-button @click="inspectSource(row)">核对冻结检验</el-button></template></el-table-column></el-table>
        </el-tab-pane>
      </el-tabs>
      <p v-if="error" role="alert">{{ error }}</p><el-pagination v-if="total > pageSize" v-model:current-page="page" :page-size="pageSize" :total="total" layout="prev,pager,next" @current-change="load" />
      <el-dialog v-model="createOpen" title="新建检验项目映射草稿" width="min(850px,96vw)" @closed="clearCreate">
        <el-form v-if="allowed" label-position="top" :disabled="creating" @submit.prevent>
          <el-form-item label="来源命名空间"><el-input v-model="form.source_namespace" aria-label="映射来源命名空间" maxlength="120" placeholder="明确原系统/来源域，不从本地编码猜测" /></el-form-item>
          <div class="fields"><el-form-item v-for="field in signatureFields" :key="field.key" :label="field.label"><el-input v-model="form.signature[field.key]" :aria-label="field.label" :maxlength="field.max" /></el-form-item></div>
          <el-form-item label="结果类型"><el-select v-model="form.signature.value_kind" aria-label="映射结果类型" placeholder="明确选择"><el-option label="数值" value="numeric" /><el-option label="定性" value="qualitative" /></el-select></el-form-item>
          <p>请填写原报告单位；定性结果原本没有单位时可留空。</p>
          <el-form-item label="目标项目身份"><el-select v-model="form.analyte_key" aria-label="映射目标项目身份" placeholder="从后端允许项目中明确选择"><el-option v-for="item in analytes" :key="item.key" :label="item.label" :value="item.key" /></el-select></el-form-item>
          <el-form-item label="依据来源标识"><el-input v-model="form.evidence_reference" aria-label="映射依据来源标识" maxlength="1000" placeholder="至少5字，填写原依据标识；系统不会抓取此文字对应的URL" /></el-form-item>
          <el-form-item label="项目身份核对依据"><el-input v-model="form.rationale" aria-label="映射项目身份核对依据" type="textarea" maxlength="2000" placeholder="至少20字，说明原来源、签名和项目身份对应关系" /></el-form-item>
        </el-form><template #footer><el-button @click="createOpen = false">取消</el-button><el-button type="primary" :loading="creating" :disabled="!canCreate" @click="create">仅保存映射草稿</el-button></template>
      </el-dialog>
      <el-dialog v-model="detailOpen" :title="detailKind === 'mappings' ? '检验项目映射审核' : '冻结检验来源审计'" width="min(1100px,96vw)" @closed="clearDetail">
        <div v-if="allowed" v-loading="inspecting"><p v-if="detailError" role="alert">{{ detailError }}</p>
          <template v-if="detail && detailKind === 'mappings'">
            <p class="hash">映射 {{ detail.mapping_id }} · {{ detail.label || detail.analyte_label || detail.analyte_key }} · {{ statusLabel(detail.status) }} · v{{ detail.revision }}<br />内容摘要 {{ detail.content_hash }}<br />治理摘要 {{ detail.governance_hash }}</p><p>来源命名空间 {{ detail.source_namespace }}；{{ signatureLabel(detail.signature) }}</p><p>原依据标识：{{ detail.evidence_reference }}</p><p>项目身份依据：{{ detail.rationale }}</p><p>登记 {{ detail.created_at }}；发布 {{ detail.published_at || '未发布' }}；原审核说明 {{ detail.review_note || '未提供' }}</p>
            <template v-if="detail.status === 'draft'"><el-checkbox v-model="semanticConfirmed">我已核对目标项目语义身份</el-checkbox><el-checkbox v-model="signatureConfirmed">我已核对来源命名空间和完整原签名</el-checkbox><el-input v-model="reviewNote" aria-label="项目映射审核说明" type="textarea" maxlength="2000" placeholder="至少20字，说明审核依据" /><el-button type="primary" :disabled="!semanticConfirmed || !signatureConfirmed || reviewNote.trim().length < 20" :loading="acting" @click="publish">审核并发布此映射版本</el-button></template>
          </template>
          <ai-laboratory-findings v-if="detail && detailKind === 'sources'" :source="detail" :expected-patient-id="detail.patient_id" :expected-admission-id="detail.admission_id" />
          <template v-if="detail && detail.status !== 'revoked' && (detailKind === 'mappings' || detail.can_revoke === true)"><el-input v-model="revokeReason" aria-label="检验治理撤销依据" type="textarea" maxlength="1000" placeholder="至少5字，明确撤销原因；不能恢复原版本" /><el-button type="danger" :disabled="revokeReason.trim().length < 5" :loading="acting" @click="revoke">撤销此{{ detailKind === 'mappings' ? '映射版本' : '检验来源' }}</el-button></template>
          <p v-if="detail?.status === 'revoked'">已撤销 {{ detail.revoked_at || '未提供' }}：{{ detail.revoke_reason || '未提供' }}。冻结原版本供审计，不自动恢复或启用。</p>
        </div><template #footer><el-button @click="detailOpen = false">关闭</el-button></template>
      </el-dialog>
    </template>
  </section>
</template>
<script setup>
import { computed, onActivated, onBeforeUnmount, onDeactivated, ref, watch } from "vue";
import { useStore } from "vuex";
import { ElMessage } from "element-plus";
import AiLaboratoryFindings from "@/components/AILaboratoryFindings/index.vue";
import { createLabMapping, getAdminLabSource, getAdminLabSources, getLabMapping, getLabMappingOptions, getLabMappings, labSourceMatches, publishLabMapping, revokeInpatientLabSource, revokeLabMapping } from "@/api/inpatientLaboratory";
const store = useStore(), roles = computed(() => store.getters["user/permissions"] || []), allowed = computed(() => !!store.state.user.accessToken && roles.value.includes("super_admin"));
const tab = ref("mappings"), mappingStatus = ref(""), filters = ref({ patient_id: "", admission_id: "", status: "" }), items = ref([]), total = ref(null), page = ref(1), pageSize = 50, loading = ref(false), error = ref(""), analytes = ref([]);
const emptyForm = () => ({ source_namespace: "", signature: { code_system: "", code: "", unit: "", method: "", specimen_type: "", value_kind: "" }, analyte_key: "", evidence_reference: "", rationale: "" });
const signatureFields = [{ key: "code_system", label: "映射原编码体系", max: 80 }, { key: "code", label: "映射原项目编码", max: 80 }, { key: "unit", label: "映射原单位", max: 40 }, { key: "method", label: "映射原检测方法", max: 100 }, { key: "specimen_type", label: "映射原标本类型", max: 80 }];
const form = ref(emptyForm()), createOpen = ref(false), creating = ref(false), detail = ref(null), detailKind = ref("mappings"), detailOpen = ref(false), inspecting = ref(false), detailError = ref(""), semanticConfirmed = ref(false), signatureConfirmed = ref(false), reviewNote = ref(""), revokeReason = ref(""), acting = ref(false);
let epoch = 0, listSequence = 0, detailSequence = 0, createSequence = 0, inactive = false;
const session = () => JSON.stringify([store.state.user.accessToken, roles.value]), queryKey = () => JSON.stringify([tab.value, mappingStatus.value, filters.value, page.value]);
const capture = () => ({ epoch, session: session() }), current = ticket => ticket.epoch === epoch && ticket.session === session() && allowed.value && !inactive;
const statusLabel = value => ({ draft: "草稿", published: "已发布", active: "活动", revoked: "已撤销" }[value] || "状态未知");
const signatureLabel = value => value ? `${value.code_system}:${value.code} · ${value.unit ?? '无单位（原定性）'} · ${value.method} · ${value.specimen_type} · ${value.value_kind}` : "签名未提供";
const canCreate = computed(() => allowed.value && !creating.value && form.value.source_namespace.trim().length >= 2 && ["code_system", "code", "method", "specimen_type"].every(key => form.value.signature[key].trim()) && ["numeric", "qualitative"].includes(form.value.signature.value_kind) && (form.value.signature.value_kind === "qualitative" || !!form.value.signature.unit.trim()) && analytes.value.some(item => item.key === form.value.analyte_key) && form.value.evidence_reference.trim().length >= 5 && form.value.rationale.trim().length >= 20);
function clearCreate() { createSequence++; createOpen.value = false; form.value = emptyForm(); creating.value = false; }
function clearDetail() { detailSequence++; detail.value = null; detailError.value = ""; inspecting.value = false; semanticConfirmed.value = false; signatureConfirmed.value = false; reviewNote.value = ""; revokeReason.value = ""; acting.value = false; }
function clearAll() { epoch++; listSequence++; clearCreate(); clearDetail(); detailOpen.value = false; items.value = []; analytes.value = []; total.value = null; loading.value = false; error.value = ""; }
async function loadOptions() { if (!allowed.value || inactive) return; const ticket = capture(); try { const response = await getLabMappingOptions(); if (!current(ticket)) return; const values = response.data?.analytes; if (!Array.isArray(values)) throw new Error("项目身份选项格式不完整"); analytes.value = values.map(item => typeof item === "string" ? { key: item, label: item } : { key: item.key ?? item.analyte_key, label: item.label ?? item.name ?? item.key ?? item.analyte_key }).filter(item => typeof item.key === "string" && item.key); } catch (failure) { if (current(ticket)) error.value = failure?.message || "允许映射的项目目录未能读取"; } }
async function load() { if (!allowed.value || inactive) return; const ticket = capture(), sequence = ++listSequence, key = queryKey(); let params; try { const patient = filters.value.patient_id.trim(); if (tab.value === "sources" && patient && (!/^[1-9]\d*$/.test(patient) || !Number.isSafeInteger(Number(patient)))) throw new Error("患者ID须为正整数"); params = { page: page.value, page_size: pageSize, ...(tab.value === "mappings" ? (mappingStatus.value ? { status: mappingStatus.value } : {}) : { ...(patient ? { patient_id: Number(patient) } : {}), ...(filters.value.admission_id.trim() ? { admission_id: filters.value.admission_id.trim() } : {}), ...(filters.value.status ? { status: filters.value.status } : {}) }) }; } catch (failure) { error.value = failure.message; return; } loading.value = true; error.value = ""; items.value = []; try { const response = await (tab.value === "mappings" ? getLabMappings(params) : getAdminLabSources(params)); if (!current(ticket) || sequence !== listSequence || key !== queryKey()) return; const values = response.data?.items; if (!Array.isArray(values) || (tab.value === "sources" && values.some(row => (params.patient_id && row.patient_id !== params.patient_id) || (params.admission_id && row.admission_id !== params.admission_id)))) throw new Error("治理目录与指定范围不一致"); items.value = values; total.value = response.data.total; } catch (failure) { if (current(ticket) && sequence === listSequence && key === queryKey()) { items.value = []; error.value = failure?.message || "治理目录未能读取"; } } finally { if (current(ticket) && sequence === listSequence && key === queryKey()) loading.value = false; } }
function openCreate() { if (!allowed.value || inactive) return; clearCreate(); createOpen.value = true; }
async function create() { if (!canCreate.value || inactive) return; const ticket = capture(), sequence = createSequence; creating.value = true; const payload = { ...form.value, signature: { ...form.value.signature, unit: form.value.signature.unit || null } }; try { const response = await createLabMapping(payload); if (!current(ticket) || sequence !== createSequence || !createOpen.value) return; if (response.data?.status !== "draft" || response.data.source_namespace !== payload.source_namespace || response.data.analyte_key !== payload.analyte_key || response.data.revision !== 1 || !/^[a-f0-9]{64}$/.test(response.data.content_hash || "") || Object.keys(payload.signature).some(key => response.data.signature?.[key] !== payload.signature[key])) throw new Error("映射草稿回执与所填来源和项目不一致"); clearCreate(); ElMessage.success("已保存映射草稿，尚未发布或启用AI"); await load(); } catch (failure) { if (current(ticket) && sequence === createSequence) error.value = failure?.message || "映射草稿保存失败"; } finally { if (current(ticket) && sequence === createSequence) creating.value = false; } }
async function inspectMapping(row) { await inspect("mappings", row); }
async function inspectSource(row) { await inspect("sources", row); }
async function inspect(kind, row) { if (!allowed.value || inactive) return; clearDetail(); const ticket = capture(), sequence = detailSequence; detailKind.value = kind; detailOpen.value = true; inspecting.value = true; try { const response = await (kind === "mappings" ? getLabMapping(row.mapping_id) : getAdminLabSource(row.lab_source_id)); if (!current(ticket) || sequence !== detailSequence || !detailOpen.value) return; if (kind === "mappings" ? response.data?.mapping_id !== row.mapping_id : response.data?.lab_source_id !== row.lab_source_id || !labSourceMatches(response.data, row.patient_id, row.admission_id)) throw new Error("治理原详情回执与指定来源不一致"); detail.value = response.data; } catch (failure) { if (current(ticket) && sequence === detailSequence && detailOpen.value) detailError.value = failure?.message || "治理原详情未能核对"; } finally { if (current(ticket) && sequence === detailSequence) inspecting.value = false; } }
async function publish() { if (!allowed.value || inactive || detail.value?.status !== "draft" || !semanticConfirmed.value || !signatureConfirmed.value || reviewNote.value.trim().length < 20 || acting.value) return; await act("publish"); }
async function revoke() { if (!allowed.value || inactive || !detail.value || detail.value.status === "revoked" || revokeReason.value.trim().length < 5 || acting.value || (detailKind.value === "sources" && detail.value.can_revoke !== true)) return; await act("revoke"); }
async function act(action) { const ticket = capture(), sequence = detailSequence, original = detail.value, kind = detailKind.value; const body = action === "publish" ? { expected_revision: original.revision, semantic_confirmed: true, source_signature_confirmed: true, review_note: reviewNote.value.trim() } : { expected_revision: original.revision, reason: revokeReason.value.trim(), ...(kind === "sources" ? { patient_id: original.patient_id, admission_id: original.admission_id } : {}) }; acting.value = true; try { const response = await (action === "publish" ? publishLabMapping(original.mapping_id, body) : kind === "mappings" ? revokeLabMapping(original.mapping_id, body) : revokeInpatientLabSource(original.lab_source_id, body)); if (!current(ticket) || sequence !== detailSequence || !detailOpen.value) return; if (kind === "mappings" ? response.data?.mapping_id !== original.mapping_id : response.data?.lab_source_id !== original.lab_source_id || !labSourceMatches(response.data, original.patient_id, original.admission_id)) throw new Error("治理动作回执与原版本不一致"); if (response.data.status !== (action === "publish" ? "published" : "revoked") || response.data.revision !== original.revision + 1 || response.data.content_hash !== original.content_hash) throw new Error("治理动作状态、版本或内容摘要与原版本不一致"); detail.value = response.data; reviewNote.value = ""; revokeReason.value = ""; semanticConfirmed.value = false; signatureConfirmed.value = false; await load(); } catch (failure) { if (current(ticket) && sequence === detailSequence) detailError.value = failure?.message || "治理动作失败，请刷新核对版本和权限"; } finally { if (current(ticket) && sequence === detailSequence) acting.value = false; } }
watch([tab, mappingStatus, () => JSON.stringify(filters.value)], () => { listSequence++; page.value = 1; items.value = []; total.value = null; detailOpen.value = false; clearDetail(); load(); }, { flush: "sync" });
watch(session, () => { clearAll(); loadOptions(); load(); }, { immediate: true, flush: "sync" });
onDeactivated(() => { inactive = true; clearAll(); }); onActivated(() => { if (inactive) { inactive = false; clearAll(); loadOptions(); load(); } }); onBeforeUnmount(() => { inactive = true; clearAll(); });
</script>
<style scoped>.fields { display: grid; grid-template-columns: repeat(auto-fit,minmax(230px,1fr)); gap: 12px; }.hash { overflow-wrap: anywhere; }p { line-height: 1.7; }.el-checkbox { display: flex; white-space: normal; margin: 12px 0; }.el-button { margin-top: 10px; }</style>
